exec('\nfrom __future__ import annotations\n\nimport datetime as dt\nimport time\nimport warnings\nfrom pathlib import Path\nfrom urllib.parse import quote_plus\nimport xml.etree.ElementTree as ET\n\nimport numpy as np\nimport pandas as pd\nimport plotly.graph_objects as go\nimport requests\nimport streamlit as st\nimport yfinance as yf\n\nfrom sklearn.linear_model import Ridge, ElasticNet, HuberRegressor, Lasso\nfrom sklearn.ensemble import ExtraTreesRegressor, RandomForestRegressor, GradientBoostingRegressor, VotingRegressor, HistGradientBoostingRegressor\nfrom sklearn.metrics import mean_squared_error\n\nwarnings.filterwarnings("ignore")\nROOT = Path(__file__).resolve().parents[1]\n\n# =============================================================================\n# MAPS AND LEXICON\n# =============================================================================\n\nMAJOR_INDICES = {\n    "S&P 500": "^GSPC", "Nasdaq 100": "^NDX", "Dow Jones": "^DJI",\n    "Russell 2000": "^RUT", "Russell 1000": "^RUI", "Russell 3000": "^RUA",\n    "NYSE Composite": "^NYA", "S&P Equal Weight ETF": "RSP", "Russell 2000 ETF": "IWM",\n    "US Industrials": "XLI", "US Materials": "XLB", "US Energy": "XLE", "US Technology": "XLK",\n    "Euro Stoxx 50": "^STOXX50E", "DAX Germany": "^GDAXI", "CAC 40 France": "^FCHI",\n    "FTSE 100 UK": "^FTSE", "FTSE MIB Italy": "FTSEMIB.MI", "Europe ETF": "VGK",\n    "Nikkei 225 Japan": "^N225", "TOPIX Japan": "^TOPX", "Hang Seng": "^HSI",\n    "CSI 300 China": "000300.SS", "Shanghai Composite": "000001.SS", "Taiwan Weighted": "^TWII",\n    "KOSPI South Korea": "^KS11", "Nifty 50 India": "^NSEI", "MSCI World proxy": "URTH",\n    "Emerging Markets": "EEM", "Global Industrials": "EXI", "Global Materials": "MXI",\n}\n\nMACRO_PROXIES = {\n    "VIX volatility": "^VIX", "US dollar index": "DX-Y.NYB", "US 10Y yield": "^TNX",\n    "US 13-week yield": "^IRX", "High-yield credit": "HYG", "Investment-grade credit": "LQD",\n    "EUR/USD": "EURUSD=X", "USD/CNY": "CNY=X", "USD/JPY": "JPY=X",\n    "Gold": "GC=F", "Silver": "SI=F", "WTI oil": "CL=F", "Brent oil": "BZ=F",\n    "Natural gas": "NG=F", "Copper": "HG=F", "Semiconductors": "SOXX", "Freight proxy": "BDRY",\n}\n\nFUTURES = {\n    "WTI crude oil": "CL=F", "Brent crude oil": "BZ=F", "Natural gas": "NG=F",\n    "Copper": "HG=F", "Gold": "GC=F", "Silver": "SI=F", "Platinum": "PL=F",\n    "Palladium": "PA=F", "Iron ore proxy": "TIO=F", "US dollar index": "DX-Y.NYB",\n    "VIX volatility": "^VIX", "US 10Y yield": "^TNX", "Gold ETF": "GLD", "Silver ETF": "SLV",\n    "Oil ETF": "USO", "Natural gas ETF": "UNG", "Uranium ETF": "URA",\n    "Rare earth ETF": "REMX", "Lithium/battery ETF": "LIT", "Steel ETF": "SLX",\n    "Copper miners ETF": "COPX",\n}\n\nCORE_ASSETS = {\n    "SPY": ("SPDR S&P 500 ETF", "ETF", "broad market beta", "US equity benchmark, liquidity, risk appetite"),\n    "RSP": ("S&P 500 Equal Weight ETF", "ETF", "market breadth", "equal-weight breadth and cyclicals"),\n    "IWM": ("Russell 2000 ETF", "ETF", "US small caps", "financing conditions, domestic cyclicals"),\n    "XME": ("SPDR Metals & Mining ETF", "ETF", "mining and metals", "steel, copper, energy, China demand"),\n    "COPX": ("Global X Copper Miners ETF", "ETF", "copper miners", "copper, USD, energy, China demand"),\n    "ITA": ("iShares U.S. Aerospace & Defense ETF", "ETF", "aerospace and defense", "titanium, aluminum, nickel, defense procurement"),\n    "XAR": ("SPDR Aerospace & Defense ETF", "ETF", "aerospace supply chain", "titanium, aluminum, nickel, defense procurement"),\n    "PRNT": ("3D Printing ETF", "ETF", "additive manufacturing", "titanium powder, nickel, aluminum, LPBF, EBM, HIP, aerospace demand"),\n    "SOXX": ("iShares Semiconductor ETF", "ETF", "semiconductors", "rare earths, Taiwan, electronics, USD"),\n    "GLD": ("SPDR Gold Shares", "ETF", "gold", "safe haven, real rates, geopolitical stress"),\n    "SLV": ("iShares Silver Trust", "ETF", "silver", "precious and industrial hybrid, solar, electronics"),\n    "USO": ("United States Oil Fund", "ETF", "oil", "fuel, Middle East, inflation"),\n    "UNG": ("United States Natural Gas Fund", "ETF", "natural gas", "LNG, power, process energy"),\n    "URA": ("Global X Uranium ETF", "ETF", "uranium", "nuclear fuel, energy security"),\n    "LIT": ("Global X Lithium & Battery Tech ETF", "ETF", "battery materials", "lithium, nickel, cobalt, graphite, EV demand"),\n    "REMX": ("VanEck Rare Earth/Strategic Metals ETF", "ETF", "rare earths", "rare earths, magnets, export controls"),\n    "SLX": ("VanEck Steel ETF", "ETF", "steel", "iron ore, coking coal, steel margins"),\n}\n\nMATERIAL_CHAINS = {\n    "Copper": {\n        "proxy": ["HG=F", "CPER", "COPX"], "scenario_key": "copper",\n        "chain": "ore → concentrate → cathode → wire/rod → motors/grids/electronics",\n        "micro": "producer revenue for miners; input cost for electrification and manufacturing users",\n        "macro": "China demand, USD, rates, grid capex, industrial PMIs",\n        "keywords": ["copper", "copper mine", "grid", "electrification"],\n    },\n    "Aluminum": {\n        "proxy": ["ALI=F", "AA"], "scenario_key": "aluminum",\n        "chain": "bauxite → alumina → smelting → billet/sheet/plate → aerospace/autos/packaging",\n        "micro": "power-sensitive smelting and aerospace/lightweighting input cost",\n        "macro": "power cost, natural gas, sanctions, China smelting, aerospace build rates",\n        "keywords": ["aluminum", "aluminium", "alumina", "bauxite", "smelter"],\n    },\n    "Titanium / AM powder": {\n        "proxy": ["ATI", "TROX", "CRS"], "scenario_key": "ampm",\n        "chain": "rutile/ilmenite → sponge → ingot/bar → powder/wire → LPBF/EBM/DED/HIP parts",\n        "micro": "powder feedstock, aerospace alloy availability and AM cost stack",\n        "macro": "aerospace backlog, defense procurement, energy-intensive processing",\n        "keywords": ["titanium sponge", "titanium powder", "Ti-6Al-4V", "LPBF", "EBM", "HIP", "powder metallurgy"],\n    },\n    "Nickel / superalloys": {\n        "proxy": ["JJN", "VALE", "NILSY"], "scenario_key": "nickel",\n        "chain": "ore → Class I nickel/refining → stainless/superalloy/cathode → turbines/batteries",\n        "micro": "superalloy and battery cathode input cost; miner revenue channel",\n        "macro": "Indonesia supply, China stainless, EV demand, aerospace engine cycle",\n        "keywords": ["nickel", "superalloy", "stainless", "battery cathode"],\n    },\n    "Rare earth magnets": {\n        "proxy": ["REMX", "MP", "LYC.AX"], "scenario_key": "rare_earth",\n        "chain": "ore → separation → NdPr/Dy/Tb oxides → magnets → EV motors/wind/defense electronics",\n        "micro": "policy and processing bottleneck; high strategic sensitivity",\n        "macro": "China export controls, defense demand, EV/wind demand, strategic reserves",\n        "keywords": ["rare earth", "neodymium", "dysprosium", "magnet", "export controls"],\n    },\n    "Steel / PM inputs": {\n        "proxy": ["SLX", "TIO=F", "HCC", "MT", "NUE"], "scenario_key": "steel",\n        "chain": "iron ore/scrap/coking coal → steel → sheet/bar/powder → machinery/autos/PM parts",\n        "micro": "steel margins and manufacturing input costs; powder metallurgy base-material channel",\n        "macro": "China property/infrastructure, energy, coal, industrial capex",\n        "keywords": ["steel", "iron ore", "coking coal", "powder metallurgy"],\n    },\n    "Battery materials": {\n        "proxy": ["LIT", "ALB", "SQM", "NMG"], "scenario_key": "battery",\n        "chain": "lithium/nickel/cobalt/graphite → cathode/anode → cells → EV/storage",\n        "micro": "EV battery cost, margin pressure and supply concentration",\n        "macro": "EV demand, China processing, subsidies, export controls, rates",\n        "keywords": ["lithium", "cobalt", "graphite", "battery", "EV"],\n    },\n    "Uranium / nuclear": {\n        "proxy": ["URA", "URNM", "CCJ"], "scenario_key": "uranium",\n        "chain": "mine → conversion → enrichment → fuel fabrication → nuclear generation",\n        "micro": "uranium producer pricing, fuel-cycle bottlenecks and power-security theme",\n        "macro": "energy security, sanctions, utility contracting, nuclear policy",\n        "keywords": ["uranium", "nuclear fuel", "enrichment", "energy security"],\n    },\n    "Energy/process cost": {\n        "proxy": ["CL=F", "BZ=F", "NG=F", "USO", "UNG"], "scenario_key": "energy",\n        "chain": "oil/gas/power → logistics/process heat → smelting/atomization/HIP/chemicals",\n        "micro": "fuel, power, heat treatment, atomization and HIP cost",\n        "macro": "Middle East risk, LNG, OPEC, inflation, rates",\n        "keywords": ["oil", "gas", "LNG", "fuel", "heat treatment", "HIP", "atomization"],\n    },\n    "Gold / silver hedge": {\n        "proxy": ["GC=F", "GLD", "SI=F", "SLV"], "scenario_key": "precious",\n        "chain": "precious metals → safe haven / industrial demand → ETFs/miners/electronics",\n        "micro": "hedge signal; silver also has solar/electronics demand",\n        "macro": "real rates, USD, central banks, geopolitical risk, risk appetite",\n        "keywords": ["gold", "silver", "bullion", "safe haven", "real rates"],\n    },\n}\n\nSCENARIO_DEFINITIONS = {\n    "copper": "Copper/electrification shock",\n    "aluminum": "Aluminum/lightweighting shock",\n    "nickel": "Nickel/superalloy shock",\n    "steel": "Steel/iron ore/coking coal shock",\n    "battery": "Battery materials shock",\n    "rare_earth": "Rare-earth/policy shock",\n    "uranium": "Uranium/nuclear shock",\n    "precious": "Gold/silver safe-haven shock",\n    "energy": "Oil/gas/process-cost shock",\n    "usd": "US dollar shock",\n    "rates": "Rates/yield shock",\n    "vix": "VIX/risk-off shock",\n    "credit": "Credit-spread shock",\n    "china": "China demand shock",\n    "eu": "Europe industrial shock",\n    "defense": "Defense spending shock",\n    "aerospace": "Aerospace backlog shock",\n    "semis": "Semiconductor cycle shock",\n    "ampm": "AM/powder metallurgy input shock",\n    "freight": "Shipping/freight shock",\n    "policy": "Sanctions/export-control shock",\n}\n\n# =============================================================================\n# DATA LOADING\n# =============================================================================\n\ndef load_companies():\n    p1 = ROOT / "data/global_manufacturing_universe_extended.csv"\n    p2 = ROOT / "data/manufacturing_company_universe.csv"\n    for p in [p1, p2]:\n        try:\n            if p.exists():\n                df = pd.read_csv(p)\n                for c in ["ticker", "company", "country", "region", "industry_group", "material_link", "why_relevant"]:\n                    if c not in df.columns:\n                        df[c] = ""\n                if not df.empty:\n                    return df.drop_duplicates("ticker")\n        except Exception:\n            pass\n    return pd.DataFrame()\n\nCOMPANIES = load_companies()\n\ndef compatible_period(interval, period):\n    if interval == "1m":\n        return period if period in ["1d", "5d"] else "5d"\n    if interval in ["5m", "15m", "30m", "60m"]:\n        return period if period in ["1d", "5d", "1mo", "3mo", "6mo"] else "60d"\n    return period\n\ndef delta_for(interval, bars):\n    if interval.endswith("m"):\n        return dt.timedelta(minutes=int(interval[:-1]) * bars)\n    return dt.timedelta(days=bars)\n\ndef fmt_num(x):\n    if x is None or pd.isna(x):\n        return ""\n    try:\n        x = float(x)\n    except Exception:\n        return str(x)\n    if abs(x) >= 1e12:\n        return f"{x/1e12:.2f}T"\n    if abs(x) >= 1e9:\n        return f"{x/1e9:.2f}B"\n    if abs(x) >= 1e6:\n        return f"{x/1e6:.2f}M"\n    if abs(x) >= 1e3:\n        return f"{x/1e3:.2f}K"\n    return f"{x:,.2f}"\n\ndef fmt_pct(x):\n    return "" if pd.isna(x) else f"{x*100:.2f}%"\n\ndef zscore(s, w):\n    w = max(3, int(w))\n    m = s.rolling(w, min_periods=max(3, w // 3)).mean()\n    sd = s.rolling(w, min_periods=max(3, w // 3)).std()\n    return ((s - m) / sd).replace([np.inf, -np.inf], np.nan)\n\ndef asset_profile(ticker):\n    if ticker in CORE_ASSETS:\n        name, typ, group, link = CORE_ASSETS[ticker]\n        return name, typ, group, link, "", ""\n    r = COMPANIES[COMPANIES["ticker"].astype(str) == ticker]\n    if not r.empty:\n        row = r.iloc[0]\n        return str(row["company"]), "equity", str(row["industry_group"]), str(row["material_link"]), str(row["country"]), str(row["region"])\n    for name, t in {**FUTURES, **MAJOR_INDICES, **MACRO_PROXIES}.items():\n        if t == ticker:\n            typ = "index" if ticker in MAJOR_INDICES.values() or ticker.startswith("^") else "future/macro"\n            return name, typ, name, name, "", ""\n    return ticker, "instrument", "unclassified", ticker, "", ""\n\ndef relevant_chains(ticker):\n    name, typ, group, link, country, region = asset_profile(ticker)\n    txt = f"{ticker} {name} {typ} {group} {link} {country} {region}".lower()\n    hits = []\n    for ch, spec in MATERIAL_CHAINS.items():\n        if ch.lower().split()[0] in txt or any(k.lower() in txt for k in spec["keywords"]):\n            hits.append(ch)\n    if not hits:\n        if any(w in txt for w in ["aerospace", "defense", "engine"]):\n            hits = ["Titanium / AM powder", "Aluminum", "Nickel / superalloys", "Rare earth magnets", "Energy/process cost"]\n        elif any(w in txt for w in ["mining", "metal", "copper"]):\n            hits = ["Copper", "Steel / PM inputs", "Energy/process cost", "Gold / silver hedge"]\n        elif "semiconductor" in txt:\n            hits = ["Rare earth magnets", "Copper", "Gold / silver hedge", "Energy/process cost"]\n        elif "battery" in txt or "ev" in txt:\n            hits = ["Battery materials", "Nickel / superalloys", "Rare earth magnets"]\n        elif "gold" in txt or "silver" in txt:\n            hits = ["Gold / silver hedge"]\n        elif "oil" in txt or "gas" in txt or "energy" in txt:\n            hits = ["Energy/process cost"]\n    return [h for h in hits if h in MATERIAL_CHAINS]\n\n@st.cache_data(ttl=45, show_spinner=False)\ndef download_ohlcv(tickers, period, interval):\n    tickers = sorted(set([t for t in tickers if isinstance(t, str) and t.strip()]))\n    if not tickers:\n        return pd.DataFrame(), pd.DataFrame(), []\n    raw = yf.download(tickers, period=period, interval=interval, auto_adjust=False, progress=False, threads=True)\n    if raw.empty:\n        return pd.DataFrame(), pd.DataFrame(), tickers\n    if isinstance(raw.columns, pd.MultiIndex):\n        close = raw["Close"].copy() if "Close" in raw.columns.get_level_values(0) else pd.DataFrame()\n        volume = raw["Volume"].copy() if "Volume" in raw.columns.get_level_values(0) else pd.DataFrame(index=close.index)\n    else:\n        close = raw[["Close"]].copy()\n        volume = raw[["Volume"]].copy() if "Volume" in raw.columns else pd.DataFrame(index=close.index)\n        if len(tickers) == 1:\n            close.columns = tickers\n            if not volume.empty:\n                volume.columns = tickers\n    close = close.dropna(axis=1, how="all").ffill().dropna(how="all")\n    volume = volume.reindex(index=close.index).dropna(axis=1, how="all") if not volume.empty else pd.DataFrame(index=close.index)\n    missing = [t for t in tickers if t not in close.columns]\n    return close, volume, missing\n\n@st.cache_data(ttl=3600, show_spinner=False)\ndef quote_metadata(tickers):\n    rows = []\n    for t in sorted(set(tickers)):\n        name, typ, group, link, country, region = asset_profile(t)\n        data = {}\n        try:\n            tk = yf.Ticker(t)\n            fi = {}\n            try: fi = dict(tk.fast_info)\n            except Exception: pass\n            info = {}\n            try: info = tk.info or {}\n            except Exception: pass\n            data = {\n                "currency": fi.get("currency") or info.get("currency"),\n                "market_cap": fi.get("market_cap") or info.get("marketCap"),\n                "shares": fi.get("shares") or info.get("sharesOutstanding"),\n                "avg_volume": fi.get("three_month_average_volume") or info.get("averageVolume") or info.get("averageVolume10days"),\n                "fifty_two_week_high": fi.get("year_high") or info.get("fiftyTwoWeekHigh"),\n                "fifty_two_week_low": fi.get("year_low") or info.get("fiftyTwoWeekLow"),\n                "sector": info.get("sector"),\n                "industry": info.get("industry"),\n                "beta_meta": info.get("beta"),\n                "trailing_pe": info.get("trailingPE"),\n                "forward_pe": info.get("forwardPE"),\n                "enterprise_value": info.get("enterpriseValue"),\n            }\n        except Exception:\n            pass\n        rows.append({"ticker": t, "name": name, "type": typ, "group": group, "country": country, "region": region, "material/process link": link, **data})\n    return pd.DataFrame(rows)\n\n@st.cache_data(ttl=360, show_spinner=False)\ndef gdelt_news(query, n=80):\n    try:\n        r = requests.get("https://api.gdeltproject.org/api/v2/doc/doc",\n                         params={"query": query, "mode": "ArtList", "format": "json", "maxrecords": n, "sort": "HybridRel"},\n                         timeout=10)\n        if r.status_code != 200: return pd.DataFrame()\n        return pd.DataFrame([{"title": a.get("title",""), "source": a.get("domain",""), "date": a.get("seendate",""), "url": a.get("url","")} for a in r.json().get("articles", [])])\n    except Exception:\n        return pd.DataFrame()\n\n@st.cache_data(ttl=900, show_spinner=False)\ndef google_news(query, n=60):\n    try:\n        url = "https://news.google.com/rss/search?q=" + quote_plus(query) + "&hl=en-US&gl=US&ceid=US:en"\n        r = requests.get(url, timeout=10, headers={"User-Agent": "MatQuantLab"})\n        if r.status_code != 200: return pd.DataFrame()\n        root = ET.fromstring(r.content)\n        rows = []\n        for item in root.findall(".//item")[:n]:\n            rows.append({"title": (item.findtext("title") or "").strip(), "source": "Google News", "date": (item.findtext("pubDate") or "").strip(), "url": (item.findtext("link") or "").strip()})\n        return pd.DataFrame(rows)\n    except Exception:\n        return pd.DataFrame()\n\n# =============================================================================\n# ANALYTICS\n# =============================================================================\n\ndef market_tape(close, volume, tickers, meta, benchmark="SPY"):\n    rows = []\n    bench_ret = close[benchmark].pct_change() if benchmark in close.columns else None\n    for t in tickers:\n        if t not in close.columns: continue\n        s = close[t].dropna()\n        if s.empty: continue\n        ret_series = s.pct_change()\n        v = volume[t].dropna() if t in volume.columns else pd.Series(dtype=float)\n        last = float(s.iloc[-1])\n        def ret(b):\n            return np.nan if len(s) <= b else float(s.iloc[-1] / s.iloc[-1-b] - 1)\n        vol_last = float(v.iloc[-1]) if not v.empty else np.nan\n        dollar_vol = vol_last * last if pd.notna(vol_last) else np.nan\n        z20s = zscore(ret_series, min(20, max(3, len(s)//4))).dropna()\n        z20 = float(z20s.iloc[-1]) if not z20s.empty else np.nan\n        high = float(s.rolling(min(252, len(s))).max().iloc[-1])\n        low = float(s.rolling(min(252, len(s))).min().iloc[-1])\n        realized_vol = float(ret_series.tail(60).std() * np.sqrt(252)) if len(s) > 65 else np.nan\n        # computed beta/alpha vs SPY over recent history\n        beta_calc, alpha_20 = np.nan, np.nan\n        if bench_ret is not None and t != benchmark:\n            joined = pd.concat([ret_series.rename("r"), bench_ret.rename("b")], axis=1).dropna().tail(252)\n            if len(joined) > 30 and joined["b"].var() > 0:\n                beta_calc = float(joined["r"].cov(joined["b"]) / joined["b"].var())\n                alpha_20 = ret(20) - beta_calc * float((close[benchmark].dropna().iloc[-1] / close[benchmark].dropna().iloc[-21] - 1)) if benchmark in close.columns and len(close[benchmark].dropna()) > 21 and len(s) > 21 else np.nan\n        m = meta[meta["ticker"] == t]\n        md = m.iloc[0].to_dict() if not m.empty else {}\n        rows.append({\n            "ticker": t, "name": md.get("name", asset_profile(t)[0]), "type": md.get("type", asset_profile(t)[1]),\n            "last": last, "currency": md.get("currency",""), "volume": vol_last, "dollar volume": dollar_vol,\n            "avg volume": md.get("avg_volume", np.nan), "market cap/value": md.get("market_cap", np.nan),\n            "enterprise value": md.get("enterprise_value", np.nan), "1 bar": ret(1), "5 bars": ret(5), "20 bars": ret(20),\n            "realized vol": realized_vol, "beta vs SPY": beta_calc, "20-bar alpha vs SPY": alpha_20,\n            "52w high": md.get("fifty_two_week_high", high), "52w low": md.get("fifty_two_week_low", low),\n            "distance from 52w high": (last / md.get("fifty_two_week_high", high) - 1) if md.get("fifty_two_week_high", high) else np.nan,\n            "z-score": z20, "tape state": "stretched higher" if z20 > 1 else "stretched lower" if z20 < -1 else "balanced",\n            "sector": md.get("sector",""), "industry": md.get("industry",""),\n        })\n    return pd.DataFrame(rows)\n\ndef build_features(close, assets, shock_window):\n    n = len(close)\n    w = max(3, min(shock_window, max(3, n//5))) if n < 200 else max(5, min(shock_window, 100))\n    lag = max(1, min(w, max(1, n//4)))\n    feat = pd.DataFrame(index=close.index)\n    meta = []\n    for t in assets:\n        if t in close.columns:\n            c = f"asset:{t}"\n            feat[c] = zscore(close[t].pct_change(lag), w)\n            meta.append((c, t, "selected instrument normalized move"))\n    chains = []\n    for t in assets: chains += relevant_chains(t)\n    if not chains: chains = list(MATERIAL_CHAINS.keys())\n    for ch in sorted(set(chains)):\n        for proxy in MATERIAL_CHAINS[ch]["proxy"]:\n            if proxy in close.columns:\n                c = f"chain:{ch}"\n                feat[c] = zscore(close[proxy].pct_change(lag), w)\n                meta.append((c, proxy, MATERIAL_CHAINS[ch]["chain"]))\n                break\n    for label, t in MACRO_PROXIES.items():\n        if t in close.columns:\n            c = f"macro:{label}"\n            feat[c] = zscore(close[t].pct_change(lag), w)\n            meta.append((c, t, "macro/regime proxy"))\n    am_cols = [c for c in feat.columns if any(k in c for k in ["Titanium", "Nickel", "Aluminum", "Energy/process", "Steel", "AM", "powder"])]\n    if am_cols: feat["basket:AM and powder metallurgy"] = feat[am_cols].mean(axis=1)\n    chain_cols = [c for c in feat.columns if c.startswith("chain:")]\n    feat["basket:material chain pressure"] = feat[chain_cols].mean(axis=1) if chain_cols else feat.mean(axis=1)\n    macro_cols = [c for c in feat.columns if c.startswith("macro:")]\n    feat["basket:macro pressure"] = feat[macro_cols].mean(axis=1) if macro_cols else pd.Series(0, index=feat.index)\n    feat = feat.replace([np.inf, -np.inf], np.nan).ffill().fillna(0)\n    return feat, pd.DataFrame(meta, columns=["feature","source ticker","meaning"]), w\n\ndef driver_table(features):\n    latest = features.iloc[-1]\n    rows = []\n    for c, val in latest.items():\n        val = float(val)\n        if c.startswith("asset:"): bucket = "micro / selected ticker"\n        elif c.startswith("chain:"): bucket = "material chain"\n        elif c.startswith("macro:"): bucket = "macro regime"\n        elif c.startswith("basket:"): bucket = "basket"\n        else: bucket = "other"\n        rows.append({"driver": c, "bucket": bucket, "score": val, "abs score": abs(val)})\n    return pd.DataFrame(rows).sort_values("abs score", ascending=False)\n\ndef transmission_map(assets, features):\n    latest = features.iloc[-1]\n    rows = []\n    for t in assets:\n        chains = relevant_chains(t)\n        cols = [f"chain:{c}" for c in chains if f"chain:{c}" in features.columns]\n        if "basket:AM and powder metallurgy" in features.columns and any(w in " ".join(asset_profile(t)).lower() for w in ["powder", "additive", "aerospace", "titanium", "hip", "lpbf"]):\n            cols.append("basket:AM and powder metallurgy")\n        if not cols:\n            cols = ["basket:material chain pressure"] if "basket:material chain pressure" in features.columns else list(features.columns[:2])\n        score = float(latest[cols].mean()) if cols else 0\n        reading = "close to current shock path" if score > .75 else "inputs easing around this instrument" if score < -.75 else "mixed / not strongly exposed right now"\n        name, typ, group, link, country, region = asset_profile(t)\n        rows.append({"ticker":t, "name":name, "type":typ, "group":group, "country":country, "region":region, "linked chains":", ".join(chains) if chains else "general market/macro", "transmission score":score, "reading":reading, "main path":" → ".join([x.replace("chain:","").replace("basket:","") for x in cols[:5]])})\n    return pd.DataFrame(rows).sort_values("transmission score", ascending=False)\n\ndef interpret_driver(driver, score, focus):\n    name, typ, group, link, country, region = asset_profile(focus)\n    direction = "upward pressure" if score > 0 else "downward/easing pressure"\n    mag = "large" if abs(score) >= 1.5 else "moderate" if abs(score) >= .75 else "small"\n    if driver.startswith("chain:"):\n        ch = driver.split(":",1)[1]\n        spec = MATERIAL_CHAINS.get(ch, {})\n        if any(w in group.lower() for w in ["mining", "copper", "gold", "rare", "uranium", "energy", "steel", "aluminum"]):\n            effect = "can be a revenue/pricing tailwind if demand-driven, but a risk if it is caused by disruption."\n        else:\n            effect = spec.get("micro", "transmits through input cost, supply availability or demand.")\n        return f"{driver}: {mag} {direction}. For {focus} ({group}), read it as: {effect}"\n    if driver.startswith("macro:VIX"):\n        return f"{driver}: {mag} {direction}. Higher VIX usually lowers risk appetite and hurts small-cap, cyclical, AM and high-beta instruments."\n    if driver.startswith("macro:US dollar"):\n        return f"{driver}: {mag} {direction}. Dollar strength often pressures commodities and non-US cyclicals; weakness often supports commodities."\n    if driver.startswith("macro:US 10Y") or driver.startswith("macro:US 13"):\n        return f"{driver}: {mag} {direction}. Higher rates can compress duration/growth assets and pressure financing-sensitive cyclicals."\n    if driver.startswith("basket:AM"):\n        return f"{driver}: {mag} {direction}. Captures titanium/nickel/aluminum/process-energy pressure linked to LPBF, EBM, DED, HIP and PM."\n    return f"{driver}: {mag} {direction}."\n\n# =============================================================================\n# ML SIGNALS\n# =============================================================================\n\ndef model_set():\n    return {\n        "Ridge": Ridge(alpha=8),\n        "ElasticNet": ElasticNet(alpha=.01, l1_ratio=.2, random_state=42),\n        "Lasso": Lasso(alpha=.001, random_state=42),\n        "Huber": HuberRegressor(epsilon=1.35, alpha=.0001),\n        "RandomForest": RandomForestRegressor(n_estimators=120, max_depth=4, random_state=42, n_jobs=-1),\n        "ExtraTrees": ExtraTreesRegressor(n_estimators=180, max_depth=5, random_state=42, n_jobs=-1),\n        "GradientBoosting": GradientBoostingRegressor(max_depth=2, random_state=42),\n        "HistGradientBoosting": HistGradientBoostingRegressor(max_iter=120, max_leaf_nodes=15, random_state=42),\n        "Blended": VotingRegressor([\n            ("ridge", Ridge(alpha=8)),\n            ("trees", ExtraTreesRegressor(n_estimators=90, max_depth=4, random_state=42, n_jobs=-1)),\n            ("gb", GradientBoostingRegressor(max_depth=2, random_state=42)),\n        ]),\n    }\n\ndef fit_eval(model, Xtr, ytr, Xte, yte):\n    model.fit(Xtr, ytr)\n    p = model.predict(Xte)\n    corr = pd.Series(p).corr(pd.Series(yte.values))\n    corr = 0 if pd.isna(corr) else float(corr)\n    rmse = float(mean_squared_error(yte, p) ** .5)\n    vol = max(float(ytr.std()), 1e-8)\n    score = corr - .1 * min(rmse / vol, 5)\n    return model, p, corr, rmse, score\n\ndef importance(model, cols):\n    if hasattr(model, "feature_importances_"):\n        return pd.Series(model.feature_importances_, index=cols).sort_values(ascending=False)\n    if hasattr(model, "coef_"):\n        co = np.array(model.coef_).reshape(-1)\n        return pd.Series(np.abs(co), index=cols[:len(co)]).sort_values(ascending=False)\n    if hasattr(model, "estimators_"):\n        parts = []\n        for e in model.estimators_:\n            if hasattr(e, "feature_importances_"):\n                parts.append(pd.Series(e.feature_importances_, index=cols))\n            elif hasattr(e, "coef_"):\n                co = np.array(e.coef_).reshape(-1)\n                parts.append(pd.Series(np.abs(co), index=cols[:len(co)]))\n        if parts: return pd.concat(parts, axis=1).mean(axis=1).sort_values(ascending=False)\n    return pd.Series(0, index=cols)\n\ndef final_verdict(direction, confidence, trust, corr, alpha_20=np.nan, beta=np.nan):\n    # Research verdict: user asked for buy/sell style, but keep it as model-only diagnostic.\n    alpha_bonus = 0\n    if pd.notna(alpha_20):\n        alpha_bonus = 0.15 if alpha_20 > 0.02 else -0.15 if alpha_20 < -0.02 else 0\n    beta_penalty = 0\n    if pd.notna(beta) and beta > 1.5 and direction == "downside":\n        beta_penalty = -0.10\n    base = confidence + alpha_bonus + beta_penalty\n    if direction == "upside" and trust in ["higher", "medium"] and base >= .55 and corr > .03:\n        return "BULLISH / BUY WATCH"\n    if direction == "downside" and trust in ["higher", "medium"] and base >= .55 and corr > .03:\n        return "BEARISH / SELL-RISK WATCH"\n    if direction == "upside" and base >= .35:\n        return "SLIGHTLY BULLISH / HOLD-UPGRADE WATCH"\n    if direction == "downside" and base >= .35:\n        return "SLIGHTLY BEARISH / HEDGE-REDUCE WATCH"\n    return "NEUTRAL / NO EDGE"\n\ndef train_signal(ticker, close, features, horizon, interval, model_choice, tape_df):\n    if ticker not in close.columns or len(close[ticker].dropna()) < 20:\n        return None, None\n    px = close[ticker].dropna()\n    h = max(1, min(int(horizon), max(1, min(len(px), len(features)) // 8)))\n    def dataset(hh):\n        y = close[ticker].pct_change(hh).shift(-hh).rename("future_return")\n        X = features.copy()\n        X = X.loc[:, X.std() > 1e-9]\n        return pd.concat([X, y], axis=1, join="inner").dropna(subset=["future_return"])\n    df = dataset(h)\n    if len(df) < 30:\n        h = max(1, min(5, horizon)); df = dataset(h)\n    if len(df) < 18:\n        h = 1; df = dataset(1)\n    if len(df) < 14: return None, None\n    cols = [c for c in df.columns if c != "future_return"]\n    df[cols] = df[cols].fillna(0)\n    split = max(8, int(len(df)*.70))\n    if split >= len(df)-4: split = max(6, len(df)-5)\n    tr, te = df.iloc[:split], df.iloc[split:]\n    if len(te) < 3: return None, None\n    Xtr, ytr, Xte, yte = tr[cols], tr["future_return"], te[cols], te["future_return"]\n    models = model_set()\n    if model_choice == "Adaptive":\n        best = None\n        for nm, m in models.items():\n            try:\n                fm, p, corr, rmse, score = fit_eval(m, Xtr, ytr, Xte, yte)\n                if best is None or score > best["score"]:\n                    best = {"name":nm, "model":fm, "pred":p, "corr":corr, "rmse":rmse, "score":score}\n            except Exception:\n                pass\n        if best is None: return None, None\n        model, pred, corr, rmse, model_name = best["model"], best["pred"], best["corr"], best["rmse"], best["name"]\n    else:\n        try:\n            model, pred, corr, rmse, _ = fit_eval(models[model_choice], Xtr, ytr, Xte, yte)\n            model_name = model_choice\n        except Exception:\n            return None, None\n    latest = float(model.predict(features.iloc[[-1]][cols].fillna(0))[0])\n    vol = max(float(ytr.std()), 1e-8)\n    confidence = min(abs(latest)/(vol*1.25), 1)\n    direction = "upside" if latest > 0 else "downside"\n    strength = "strong" if confidence > .66 else "moderate" if confidence > .33 else "weak"\n    if len(te) < 8: trust, reason = "low", "few test observations"\n    elif corr > .12 and confidence > .50: trust, reason = "higher", "recent out-of-sample alignment was useful"\n    elif corr > .03 and confidence > .33: trust, reason = "medium", "recent out-of-sample alignment was positive but not strong"\n    elif corr > 0: trust, reason = "low-medium", "alignment was positive but weak"\n    else: trust, reason = "low", "validation did not support the direction"\n    imp = importance(model, cols)\n    drivers = list(imp.index[:3])\n    try:\n        until = pd.Timestamp(px.index[-1]) + delta_for(interval, h)\n        until_s = str(until)[:16]\n    except Exception: until_s = "next horizon window"\n    trw = tape_df[tape_df["ticker"] == ticker]\n    alpha_20 = trw["20-bar alpha vs SPY"].iloc[0] if not trw.empty and "20-bar alpha vs SPY" in trw else np.nan\n    beta = trw["beta vs SPY"].iloc[0] if not trw.empty and "beta vs SPY" in trw else np.nan\n    verdict = final_verdict(direction, confidence, trust, corr, alpha_20, beta)\n    invalid = "; ".join([f"{d} moves back toward 0 or flips sign" for d in drivers[:2]]) if drivers else "drivers reverse"\n    message = f"{ticker}: {verdict}. Research horizon is {h} {interval} bars. Model points {direction}; trust is {trust}: {reason}. Drivers: {\', \'.join(drivers)}. Useful until about {until_s}, or earlier if {invalid}."\n    curve = te.copy()\n    curve["prediction"] = pred\n    curve["future_return"] = yte\n    curve["diagnostic_curve"] = (1 + np.sign(curve["prediction"]) * curve["future_return"].fillna(0)).cumprod()\n    row = {\n        "ticker":ticker, "final verdict":verdict, "direction":direction, "strength":strength, "trust":trust,\n        "model":model_name, "predicted return":latest, "confidence":confidence, "test corr":corr, "rmse":rmse,\n        "beta vs SPY":beta, "20-bar alpha vs SPY":alpha_20, "horizon bars":h, "valid until":until_s,\n        "driver 1":drivers[0] if len(drivers)>0 else "", "driver 2":drivers[1] if len(drivers)>1 else "", "driver 3":drivers[2] if len(drivers)>2 else "",\n        "data start":str(pd.Timestamp(df.index[0]))[:16], "data end":str(pd.Timestamp(df.index[-1]))[:16], "message":message\n    }\n    return row, curve\n\ndef news_query(base_terms, assets):\n    terms = list(base_terms)\n    for a in assets:\n        name, typ, group, link, country, region = asset_profile(a)\n        terms += [a, name, typ, group, link, country, region]\n        for ch in relevant_chains(a):\n            terms += MATERIAL_CHAINS[ch]["keywords"] + [ch]\n    clean, seen = [], set()\n    for t in terms:\n        for p in str(t).replace("/", " ").split(","):\n            p = p.strip()\n            if p and p.lower() not in seen and len(p)<80:\n                clean.append(p); seen.add(p.lower())\n    return "(" + " OR ".join(clean[:80]) + ")"\n\ndef news_themes(news):\n    themes = {\n        "energy / fuel":["oil","gas","lng","fuel","opec","refinery","hormuz"],\n        "critical minerals":["critical minerals","rare earth","lithium","cobalt","nickel","graphite","titanium"],\n        "AM / powder metallurgy":["powder metallurgy","additive manufacturing","3d printing","metal powder","lpbf","ebm","hip"],\n        "aerospace / defense":["aerospace","defense","missile","aircraft","procurement","backlog"],\n        "China / controls":["china","taiwan","export control","sanction","tariff"],\n        "gold / silver":["gold","silver","bullion","safe haven"],\n    }\n    if news.empty: return 0.0, pd.DataFrame({"theme":list(themes.keys()), "mentions":0})\n    txt = " ".join(news["title"].fillna("").str.lower().tolist())\n    rows, score = [], 0\n    for th, words in themes.items():\n        cnt = sum(txt.count(w) for w in words)\n        rows.append({"theme":th, "mentions":cnt}); score += cnt\n    return min(score/10, 4.0), pd.DataFrame(rows).sort_values("mentions", ascending=False)\n\ndef scenario_table(assets, shocks):\n    rows = []\n    for a in assets:\n        name, typ, group, link, country, region = asset_profile(a)\n        txt = f"{a} {name} {typ} {group} {link} {country} {region}".lower()\n        score, reasons = 0, []\n        def apply(key, cond_words, producer_words=None, manuf_mult=-0.5, prod_mult=0.7):\n            nonlocal score, reasons\n            if any(w in txt for w in cond_words):\n                prod = producer_words and any(w in txt for w in producer_words)\n                mult = prod_mult if prod else manuf_mult\n                score += shocks.get(key,0)*mult\n                reasons.append(SCENARIO_DEFINITIONS[key])\n        apply("copper", ["copper","electrification","grid"], ["miner","mining","copper"], -0.55, .85)\n        apply("aluminum", ["aluminum","aerospace","auto","packaging"], ["aluminum","smelting"], -0.55, .75)\n        apply("nickel", ["nickel","superalloy","engine","battery"], ["nickel","mining"], -0.55, .8)\n        apply("steel", ["steel","machinery","auto","construction","powder metallurgy"], ["steel"], -0.5, .7)\n        apply("battery", ["battery","ev","lithium","cobalt","graphite"], ["lithium","battery materials"], -0.45, .75)\n        apply("rare_earth", ["rare","magnet","defense","semiconductor"], ["rare earth"], -0.4, .8)\n        apply("uranium", ["uranium","nuclear"], ["uranium"], -0.2, .9)\n        apply("precious", ["gold","silver","safe"], ["gold","silver"], .2, .8)\n        apply("energy", ["oil","gas","fuel","smelting","chemicals","power","aerospace"], ["energy","oil","gas"], -0.65, .8)\n        apply("defense", ["defense","missile","procurement"], ["defense"], .7, .7)\n        apply("aerospace", ["aerospace","aircraft","engine"], ["aerospace"], .65, .65)\n        apply("semis", ["semiconductor","electronics","chip"], ["semiconductor"], .65, .65)\n        apply("ampm", ["powder","additive","lpbf","ebm","hip","titanium"], ["additive"], -0.5, .55)\n        apply("freight", ["transport","logistics","autos","aerospace","industrial"], ["shipping"], -0.4, .5)\n        apply("policy", ["rare","defense","china","battery","semiconductor","titanium"], ["mining"], -0.45, .5)\n        # macro overlays\n        score += shocks.get("usd",0)*(-0.35)\n        score += shocks.get("rates",0)*(-0.35)\n        score += shocks.get("vix",0)*(-0.6)\n        score += shocks.get("credit",0)*(-0.45)\n        score += shocks.get("china",0)*(0.55 if any(w in txt for w in ["china","mining","copper","steel","autos","battery"]) else 0.15)\n        score += shocks.get("eu",0)*(0.5 if any(w in txt for w in ["europe","germany","france","italy","united kingdom","autos","aerospace"]) else 0.05)\n        reading = "scenario tailwind" if score > .5 else "scenario headwind" if score < -.5 else "mixed"\n        rows.append({"ticker":a, "scenario score":score, "reading":reading, "main channels":", ".join(reasons[:5]) or "macro beta"})\n    return pd.DataFrame(rows).sort_values("scenario score", ascending=False)\n\n# =============================================================================\n# PLOTS\n# =============================================================================\n\ndef line_chart(df, title, yaxis="value", normalize=False):\n    if df.empty:\n        st.info("No data for this chart."); return\n    x = df.copy().dropna(how="all").ffill()\n    if normalize and len(x): x = x / x.iloc[0]\n    fig = go.Figure()\n    for c in x.columns:\n        fig.add_trace(go.Scatter(x=x.index, y=x[c], name=str(c), mode="lines", hovertemplate=f"{c}<br>%{{x}}<br>%{{y:.4f}}<extra></extra>"))\n    fig.update_layout(title=title, height=420, xaxis_title="time", yaxis_title=yaxis, hovermode="x unified", margin=dict(l=20,r=20,t=55,b=30))\n    st.plotly_chart(fig, use_container_width=True)\n\ndef bar_chart(df, x, y, title):\n    if df.empty:\n        st.info("No data for this chart."); return\n    d = df.copy().sort_values(x)\n    fig = go.Figure(go.Bar(x=d[x], y=d[y], orientation="h", text=[f"{v:.2f}" for v in d[x]], textposition="auto"))\n    fig.update_layout(title=title, height=max(350, min(950, 28*len(d)+80)), xaxis_title=x, yaxis_title="", margin=dict(l=20,r=20,t=55,b=30))\n    st.plotly_chart(fig, use_container_width=True)\n\n# =============================================================================\n# APP\n# =============================================================================\n\nst.set_page_config(page_title="MatQuantLab", layout="wide")\nst.title("MatQuantLab")\nst.subheader("Market and materials intelligence for industrial assets")\nst.caption("Price, liquidity, alpha/beta, macro regime, material transmission, ML verdict, scenario risk and event context.")\n\nwith st.sidebar:\n    st.header("Research setup")\n    universe = st.radio("Universe", ["Core ETFs/assets", "Manufacturing companies", "Commodities/futures", "Major indices", "Everything"], index=4)\n    regions = st.multiselect("Region filter", sorted(COMPANIES["region"].dropna().unique().tolist()) if not COMPANIES.empty else [], default=[])\n    countries = st.multiselect("Country filter", sorted(COMPANIES["country"].dropna().unique().tolist()) if not COMPANIES.empty else [], default=[])\n    core = sorted(CORE_ASSETS.keys())\n    comp_df = COMPANIES.copy()\n    if regions: comp_df = comp_df[comp_df["region"].isin(regions)]\n    if countries: comp_df = comp_df[comp_df["country"].isin(countries)]\n    comp = sorted(comp_df["ticker"].astype(str).tolist())\n    fut = sorted(set(FUTURES.values()))\n    idx = sorted(set(MAJOR_INDICES.values()))\n    if universe == "Core ETFs/assets": choices = core\n    elif universe == "Manufacturing companies": choices = comp\n    elif universe == "Commodities/futures": choices = fut\n    elif universe == "Major indices": choices = idx\n    else: choices = sorted(set(core + comp + fut + idx))\n    default_assets = [x for x in ["SPY","IWM","COPX","XME","PRNT","GLD","USO","URA","REMX","^RUT"] if x in choices]\n    assets = st.multiselect("Instruments to analyze", choices, default=default_assets[:10])\n    focus = st.selectbox("Focus instrument", assets if assets else ["SPY"])\n    benchmark = st.selectbox("Benchmark for alpha/beta", ["SPY","IWM","RSP","^GSPC","^RUT"], index=0)\n    interval = st.selectbox("Data interval", ["1m","5m","15m","30m","60m","1d"], index=5)\n    period = st.selectbox("History", ["1d","5d","1mo","3mo","6mo","1y","2y","5y","10y"], index=7)\n    model_choice = st.selectbox("ML model selection", ["Adaptive","Ridge","ElasticNet","Lasso","Huber","RandomForest","ExtraTrees","GradientBoosting","HistGradientBoosting","Blended"], index=0)\n    horizon = st.slider("Research horizon, bars", 1, 120, 10)\n    shock_window = st.slider("Shock window, bars", 3, 150, 20)\n    fast = st.toggle("Fast mode", value=True)\n    st.markdown("**Event layer**")\n    base_terms = st.multiselect("Base event terms", sorted(["critical minerals","rare earth","export controls","sanctions","Iran","Strait of Hormuz","Red Sea","oil","gas","LNG","gold","silver","China","Taiwan","titanium powder","powder metallurgy","LPBF","EBM","HIP","aerospace backlog","defense procurement","Russell 2000","small caps","credit spread","rates"]), default=["critical minerals","rare earth","export controls","oil","gas","gold","China","powder metallurgy"])\n    extra_terms = st.text_input("Extra event terms, comma separated", value="")\n    if extra_terms: base_terms += [x.strip() for x in extra_terms.split(",") if x.strip()]\n    auto = st.toggle("Auto-refresh", value=False)\n    refresh_seconds = st.selectbox("Refresh every", [30,60,120,300], index=1)\n    if st.button("Refresh now"):\n        st.cache_data.clear(); st.rerun()\n\nif auto:\n    time.sleep(refresh_seconds); st.cache_data.clear(); st.rerun()\n\nif not assets:\n    st.warning("Select at least one instrument."); st.stop()\n\nactual_period = compatible_period(interval, period)\nchains = []\nfor a in assets: chains += relevant_chains(a)\nproxy_tickers = []\nfor ch in sorted(set(chains)):\n    proxy_tickers += MATERIAL_CHAINS[ch]["proxy"][:2 if fast else 3]\nessential = list(MACRO_PROXIES.values())[:10] + [benchmark, "SPY","IWM","RSP","^RUT","^GSPC","DX-Y.NYB","^VIX","GC=F","CL=F","NG=F","HG=F","SI=F"]\ndownload_list = sorted(set(assets + proxy_tickers + essential + ([] if fast else list(FUTURES.values()) + list(MAJOR_INDICES.values()))))\n\nclose, volume, missing = download_ohlcv(download_list, actual_period, interval)\nif close.empty:\n    st.error("No market data loaded. Try daily interval, fewer instruments or core assets."); st.stop()\n\navailable_assets = [a for a in assets if a in close.columns]\nmeta = quote_metadata(available_assets + [focus, benchmark])\ntape = market_tape(close, volume, available_assets, meta, benchmark=benchmark if benchmark in close.columns else "SPY")\nfeatures, feature_meta, used_window = build_features(close, available_assets, shock_window)\ndrivers = driver_table(features)\ntransmission = transmission_map(available_assets, features)\n\nsig_rows, curves = [], {}\nfor a in available_assets:\n    row, curve = train_signal(a, close, features, horizon, interval, model_choice, tape)\n    if row:\n        name, typ, group, link, country, region = asset_profile(a)\n        row.update({"name":name, "type":typ, "group":group, "country":country, "region":region, "material/process link":link})\n        sig_rows.append(row); curves[a] = curve\nsignals = pd.DataFrame(sig_rows)\nif not signals.empty:\n    order = {"higher":0,"medium":1,"low-medium":2,"low":3}\n    verdict_order = {"BULLISH / BUY WATCH":0,"SLIGHTLY BULLISH / HOLD-UPGRADE WATCH":1,"NEUTRAL / NO EDGE":2,"SLIGHTLY BEARISH / HEDGE-REDUCE WATCH":3,"BEARISH / SELL-RISK WATCH":4}\n    signals["_o"] = signals["trust"].map(order).fillna(9)\n    signals["_v"] = signals["final verdict"].map(verdict_order).fillna(5)\n    signals = signals.sort_values(["_o","confidence"], ascending=[True,False]).drop(columns=["_o","_v"])\n\nquery = news_query(base_terms, available_assets)\nnews = pd.concat([gdelt_news(query, 80), google_news(query, 60)], ignore_index=True)\nevent_score, theme_table = news_themes(news)\n\nfocus_tape = tape[tape["ticker"] == focus]\nlast = focus_tape["last"].iloc[0] if not focus_tape.empty else np.nan\nmc = focus_tape["market cap/value"].iloc[0] if not focus_tape.empty and "market cap/value" in focus_tape else np.nan\nvol_last = focus_tape["volume"].iloc[0] if not focus_tape.empty and "volume" in focus_tape else np.nan\nfocus_signal = signals[signals["ticker"] == focus] if not signals.empty and focus in signals["ticker"].values else pd.DataFrame()\n\nk1,k2,k3,k4,k5,k6,k7,k8 = st.columns(8)\nk1.metric("Focus", focus)\nk2.metric("Last price", fmt_num(last))\nk3.metric("Volume", fmt_num(vol_last))\nk4.metric("Market value", fmt_num(mc))\nk5.metric("Material pressure", f"{features[\'basket:material chain pressure\'].iloc[-1]:.2f}" if "basket:material chain pressure" in features else "n/a")\nk6.metric("Macro pressure", f"{features[\'basket:macro pressure\'].iloc[-1]:.2f}" if "basket:macro pressure" in features else "n/a")\nk7.metric("Event risk", f"{event_score:.2f}")\nk8.metric("Verdict", focus_signal.iloc[0]["final verdict"].split("/")[0].strip() if not focus_signal.empty else "n/a")\n\nif actual_period != period:\n    st.warning(f"{interval} data cannot reliably support {period}; this run uses {actual_period}.")\nif missing:\n    with st.expander("Unavailable tickers in this run", expanded=False):\n        st.write(", ".join(missing[:120]))\n\nif not focus_signal.empty:\n    st.info(focus_signal.iloc[0]["message"])\nelse:\n    st.info(f"{focus}: no stable ML verdict under the current setup. Use market tape, chain exposure and scenarios first.")\n\ntabs = st.tabs(["Cockpit", "Market Tape", "Alpha/Beta", "Macro & Indices", "Material Chain", "Verdicts & ML", "Scenario Engine", "News & Events", "Data Quality"])\n\nwith tabs[0]:\n    st.subheader("Cockpit")\n    st.markdown("This cockpit answers: **what is trading, what is driving it, what chain is connected, and what is the model-only verdict?**")\n    name, typ, group, link, country, region = asset_profile(focus)\n    c1,c2,c3,c4 = st.columns(4)\n    c1.metric("Name", name[:30])\n    c2.metric("Type", typ)\n    c3.metric("Country", country or "n/a")\n    c4.metric("Group", group[:28])\n    st.write(f"**Material/process link:** {link}")\n    st.markdown("### Top drivers now")\n    topd = drivers.head(10)[["driver","bucket","score"]]\n    st.dataframe(topd, use_container_width=True, hide_index=True)\n    for _, r in drivers.head(6).iterrows():\n        st.write("• " + interpret_driver(r["driver"], r["score"], focus))\n    st.markdown("### Selected tape summary")\n    show = tape.copy()\n    for c in ["last","volume","dollar volume","avg volume","market cap/value","enterprise value"]:\n        if c in show: show[c] = show[c].apply(fmt_num)\n    for c in ["1 bar","5 bars","20 bars","realized vol","20-bar alpha vs SPY","distance from 52w high"]:\n        if c in show: show[c] = show[c].apply(fmt_pct)\n    for c in ["z-score","beta vs SPY"]:\n        if c in show: show[c] = show[c].apply(lambda x: "" if pd.isna(x) else f"{x:.2f}")\n    st.dataframe(show, use_container_width=True, hide_index=True)\n\nwith tabs[1]:\n    st.subheader("Market tape: price, value and liquidity")\n    st.markdown("Actual price comes first. Indexed charts are only for comparing different units.")\n    show = tape.copy()\n    for c in ["last","volume","dollar volume","avg volume","market cap/value","enterprise value","52w high","52w low"]:\n        if c in show: show[c] = show[c].apply(fmt_num)\n    for c in ["1 bar","5 bars","20 bars","realized vol","20-bar alpha vs SPY","distance from 52w high"]:\n        if c in show: show[c] = show[c].apply(fmt_pct)\n    for c in ["z-score","beta vs SPY"]:\n        if c in show: show[c] = show[c].apply(lambda x: "" if pd.isna(x) else f"{x:.2f}")\n    st.dataframe(show, use_container_width=True, hide_index=True)\n    mode = st.radio("Chart", ["Focus raw price", "Selected raw prices", "Selected indexed", "Returns"], horizontal=True)\n    if mode == "Focus raw price":\n        cols = [focus] if focus in close.columns else []\n        for ch in relevant_chains(focus):\n            for t in MATERIAL_CHAINS[ch]["proxy"][:1]:\n                if t in close.columns: cols.append(t)\n        line_chart(close[list(dict.fromkeys(cols))], f"{focus}: actual price with relevant chain proxies", "actual price")\n    elif mode == "Selected raw prices":\n        line_chart(close[[a for a in available_assets if a in close.columns][:12]], "Selected instruments — actual prices", "actual price")\n    elif mode == "Selected indexed":\n        line_chart(close[[a for a in available_assets if a in close.columns][:14]], "Selected instruments — indexed to 1.0", "indexed", normalize=True)\n    else:\n        ret = close[[a for a in available_assets if a in close.columns][:14]].pct_change().fillna(0).cumsum()\n        line_chart(ret, "Selected instruments — cumulative return proxy", "cumulative return")\n\nwith tabs[2]:\n    st.subheader("Alpha/Beta and technical diagnostics")\n    st.markdown("Alpha/beta is computed against the selected benchmark when available. It is a diagnostic, not a guarantee.")\n    ab_cols = ["ticker","name","type","last","20 bars","realized vol","beta vs SPY","20-bar alpha vs SPY","z-score","tape state","distance from 52w high"]\n    ab = tape[[c for c in ab_cols if c in tape.columns]].copy()\n    for c in ["last"]:\n        if c in ab: ab[c] = ab[c].apply(fmt_num)\n    for c in ["20 bars","realized vol","20-bar alpha vs SPY","distance from 52w high"]:\n        if c in ab: ab[c] = ab[c].apply(fmt_pct)\n    for c in ["beta vs SPY","z-score"]:\n        if c in ab: ab[c] = ab[c].apply(lambda x: "" if pd.isna(x) else f"{x:.2f}")\n    st.dataframe(ab, use_container_width=True, hide_index=True)\n    if "beta vs SPY" in tape.columns and "20-bar alpha vs SPY" in tape.columns:\n        plot_df = tape.dropna(subset=["beta vs SPY","20-bar alpha vs SPY"])\n        if not plot_df.empty:\n            fig = go.Figure(go.Scatter(x=plot_df["beta vs SPY"], y=plot_df["20-bar alpha vs SPY"], mode="markers+text", text=plot_df["ticker"], textposition="top center"))\n            fig.update_layout(title=f"Beta vs {benchmark} and 20-bar alpha", xaxis_title="beta", yaxis_title="20-bar alpha", height=430)\n            st.plotly_chart(fig, use_container_width=True)\n\nwith tabs[3]:\n    st.subheader("Macro and indices")\n    macro_cols = [t for t in MACRO_PROXIES.values() if t in close.columns]\n    index_cols = [t for t in MAJOR_INDICES.values() if t in close.columns]\n    msel = st.multiselect("Macro proxies", macro_cols, default=macro_cols[:8])\n    if msel: line_chart(close[msel], "Macro proxies — indexed", "indexed", normalize=True)\n    isel = st.multiselect("Major indices", index_cols, default=index_cols[:10])\n    if isel: line_chart(close[isel], "Major indices — indexed", "indexed", normalize=True)\n    md = drivers[drivers["bucket"] == "macro regime"].head(12)\n    st.dataframe(md[["driver","score"]], use_container_width=True, hide_index=True)\n    for _, r in md.head(6).iterrows():\n        st.write("• " + interpret_driver(r["driver"], r["score"], focus))\n\nwith tabs[4]:\n    st.subheader("Material-chain transmission")\n    st.dataframe(transmission, use_container_width=True, hide_index=True)\n    bar_chart(transmission, "transmission score", "ticker", "Transmission score by selected instrument")\n    st.markdown("### Focus chain details")\n    for ch in relevant_chains(focus):\n        spec = MATERIAL_CHAINS[ch]\n        with st.expander(ch, expanded=True):\n            st.write(f"**Physical chain:** {spec[\'chain\']}")\n            st.write(f"**Micro channel:** {spec[\'micro\']}")\n            st.write(f"**Macro channel:** {spec[\'macro\']}")\n            loaded = [p for p in spec["proxy"] if p in close.columns]\n            if loaded: line_chart(close[loaded], f"{ch}: loaded proxies", "actual price")\n\nwith tabs[5]:\n    st.subheader("Verdicts and ML training")\n    st.markdown("Verdict labels are model-only research labels. They are not investment advice.")\n    if signals.empty:\n        st.warning("No ML verdicts for this setup. Try daily data, longer history or fewer instruments.")\n    else:\n        show = signals[["ticker","name","type","group","final verdict","direction","strength","trust","model","predicted return","confidence","test corr","beta vs SPY","20-bar alpha vs SPY","driver 1","driver 2","driver 3","horizon bars","valid until","message"]].copy()\n        for c in ["predicted return","20-bar alpha vs SPY"]:\n            show[c] = show[c].apply(fmt_pct)\n        for c in ["confidence","test corr","beta vs SPY"]:\n            show[c] = show[c].apply(lambda x: "" if pd.isna(x) else f"{x:.3f}")\n        st.dataframe(show, use_container_width=True, hide_index=True)\n        inspect = st.selectbox("Inspect ML verdict", signals["ticker"].tolist(), index=signals["ticker"].tolist().index(focus) if focus in signals["ticker"].tolist() else 0)\n        r = signals[signals["ticker"] == inspect].iloc[0]\n        v1,v2,v3,v4 = st.columns(4)\n        v1.metric("Final verdict", r["final verdict"])\n        v2.metric("Trust", r["trust"])\n        v3.metric("Predicted return", fmt_pct(r["predicted return"]))\n        v4.metric("Valid until", r["valid until"])\n        st.write(r["message"])\n        if inspect in curves:\n            line_chart(curves[inspect][["prediction","future_return"]], f"{inspect}: predicted vs realized later return", "return")\n            line_chart(curves[inspect][["diagnostic_curve"]], f"{inspect}: diagnostic curve", "index")\n        st.markdown("**Verdict rules:** bullish/sell labels require direction, confidence, validation and alpha/beta context. Low-trust signals become neutral/no-edge or watch labels.")\n\nwith tabs[6]:\n    st.subheader("Scenario engine")\n    st.markdown("Stress-test the selected instruments with macro, material, policy and process shocks.")\n    keys = list(SCENARIO_DEFINITIONS.keys())\n    shocks = {}\n    cols = st.columns(4)\n    defaults = {k:0.0 for k in keys}\n    for i, k in enumerate(keys):\n        with cols[i % 4]:\n            shocks[k] = st.slider(SCENARIO_DEFINITIONS[k], -2.0, 2.0, defaults[k], .25)\n    scen = scenario_table(available_assets, shocks)\n    st.dataframe(scen, use_container_width=True, hide_index=True)\n    bar_chart(scen, "scenario score", "ticker", "Scenario score by selected instrument")\n    st.caption("Positive scenario score = mapped tailwind. Negative = mapped headwind. This is exposure logic, not ML prediction.")\n\nwith tabs[7]:\n    st.subheader("News and events")\n    st.code(query)\n    n1,n2,n3 = st.columns(3)\n    n1.metric("Event risk", f"{event_score:.2f}")\n    n2.metric("Headlines", len(news))\n    n3.metric("Query terms", len(query.split(" OR ")))\n    st.dataframe(theme_table, use_container_width=True, hide_index=True)\n    bar_chart(theme_table.rename(columns={"mentions":"score","theme":"driver"}), "score", "driver", "Event theme intensity")\n    if news.empty:\n        st.info("No news returned. Use fewer or broader terms.")\n    else:\n        st.dataframe(news[["title","source","date","url"]].head(150), use_container_width=True, hide_index=True)\n\nwith tabs[8]:\n    st.subheader("Data quality")\n    q1,q2,q3,q4 = st.columns(4)\n    q1.metric("Requested history", period)\n    q2.metric("Actual history", actual_period)\n    q3.metric("Price rows", len(close))\n    q4.metric("Feature rows", len(features))\n    st.write(f"Price coverage: `{close.index[0]}` → `{close.index[-1]}`")\n    st.write(f"Shock window used: `{used_window}`")\n    st.dataframe(close.tail(120), use_container_width=True)\n    st.dataframe(volume.tail(120), use_container_width=True)\n    st.markdown("### Quote metadata")\n    st.dataframe(meta, use_container_width=True, hide_index=True)\n    st.markdown("### Feature metadata")\n    st.dataframe(feature_meta, use_container_width=True, hide_index=True)\n    st.markdown("### Company universe loaded")\n    st.dataframe(COMPANIES, use_container_width=True, hide_index=True)\n\nst.divider()\nst.caption("Research cockpit. Free public market/news data may be delayed, incomplete or unavailable. Verdicts are diagnostics, not investment advice.")\n')
